def f(inputs: List[Tuple[int, int, List[Tuple[int, int, int]]]]): 
    result = []

    for inp in inputs:
        result.extend(convert_int_value_to_ind(input_value) for input_value in inp[2])

    total_len = sum(ns for ns, _, _ in inputs)
    mean = sum((di + si1) / 2 for si1, _, di in result) / total_len
