    i = (low - 1)
    pi = 0
    start_i, dist = nums[low]
    end_i, dist = nums[high]

    if is_vertical:
        pivot = dist
    else:
        pivot = start_i + end_i
    while (low <= high):
        if len(nums)!= 2:
            while low <= high and (nums[low][int(is_vertical)] < pivot):
                low = low + 1
        else:
            low = high
        if (low <= high) and (nums[high][int(is_vertical)] > pivot):
            high = high - 1
        elif (low <= high) and (nums[high][int(is_vertical)] == pivot) and nums[low][int(is_vertical)] is None:
            high = high - 1
        else:
            i = i + 1
            nums[i],nums[high]=nums[high],nums[i]

    return (i + 1)

